WITH filtered_products AS (SELECT * FROM products WHERE stock_qty < 174), products_stats AS (SELECT category, COUNT(CASE WHEN brand = 'Umbrella' THEN 1 END) AS umbrella_count, SUM(CASE WHEN category = 'Grocery' THEN cost ELSE 0 END) AS grocery_cost FROM filtered_products GROUP BY category) SELECT category, umbrella_count, grocery_cost FROM products_stats WHERE grocery_cost > 43 ORDER BY grocery_cost DESC;
